def count_negatives(grid):
    rows = len(grid)
    cols = len(grid[0]) if rows else 0
    total = 0

    for row in grid:
        lo, hi = 0, cols
        while lo < hi:
            mid = (lo + hi) // 2
            if row[mid] < 0:
                hi = mid
            else:
                lo = mid + 1
        total += cols - lo

    return total

